-- Contenu du site administré par le club (spec 014) : un document JSON par type de contenu
-- (coordonnées, dojo, association, équipe, disciplines, partenaires, règlement, liens), validé par
-- le Worker (content/contenu.ts). Chaque enregistrement est aussi versionné (historique, retour
-- à une version précédente). Statut « a_completer » : visible en qualif avec un badge, jamais en prod.

CREATE TABLE contenus (
  cle         TEXT    PRIMARY KEY,
  valeur      TEXT    NOT NULL,                                  -- JSON (content/contenu.ts)
  statut      TEXT    NOT NULL DEFAULT 'publie' CHECK (statut IN ('publie', 'a_completer')),
  modifie_le  TEXT    NOT NULL DEFAULT (datetime('now')),
  modifie_par INTEGER REFERENCES users(id)
);

CREATE TABLE contenus_versions (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  cle         TEXT    NOT NULL,
  valeur      TEXT    NOT NULL,
  statut      TEXT    NOT NULL CHECK (statut IN ('publie', 'a_completer')),
  modifie_le  TEXT    NOT NULL DEFAULT (datetime('now')),
  modifie_par INTEGER REFERENCES users(id)
);

CREATE INDEX idx_contenus_versions_cle ON contenus_versions (cle, id);

-- Contenu en vigueur avant la spec 014 (content/contenu-initial.ts), première version de chacun.
INSERT INTO contenus (cle, valeur, statut) VALUES
  ('contact', '{"email":"contact@judo-condat.example","telephone":"05 00 00 00 00"}', 'a_completer'),
  ('club', '{"nomDojo":"Dojo de Condat-sur-Vienne","adresse":"9 rue Jules Ferry","codePostal":"87920","ville":"Condat-sur-Vienne","facebook":"https://www.facebook.com/p/Judo-Condat-100010470662307/","saisonResume":"De septembre à juin","saisonDetail":"Les cours sont assurés pendant toute la saison sportive, de septembre à juin. Ils ne sont pas assurés pendant les vacances scolaires et les jours fériés."}', 'publie'),
  ('association', '{"denomination":"Condat-sur-Vienne Judo","forme":"Association déclarée (loi du 1er juillet 1901)","rna":"W872010702","siren":"812 679 124","siege":"13 rue des Peupliers, 87920 Condat-sur-Vienne","creation":"avril 2015"}', 'publie'),
  ('equipe', '{"professeur":{"role":"Professeur","nom":"Jason Guillot"},"bureau":[{"role":"Président","nom":"Eric Granet"},{"role":"Trésorière","nom":"Elodie Chambon"},{"role":"Secrétaire","nom":"Catherine Granet"}]}', 'publie'),
  ('disciplines', '{"disciplines":[{"id":"judo","nom":"Judo","accroche":"Sport d’équilibre, sport éducatif, sport de défense.","enBref":"le judo pour tous les âges, dès 4 ans avec l’éveil judo","public":"Dès 4 ans avec l’éveil judo","paragraphes":["Sport d’équilibre, sport éducatif, sport de défense, le judo est adapté à toutes les tranches d’âge.","Véritable sport éducatif, le judo permet à chacun de devenir plus adroit, plus souple, plus fort, mais aussi d’apprendre à respecter des règles, de découvrir l’entraide, d’évaluer ses forces et ses faiblesses pour progresser.","Le judo est un sport pour tous qui procure un véritable équilibre. Activité de détente et de plaisir, le judo est une discipline basée sur l’échange et la progression.","L’apprentissage se fait de manière progressive, en fonction des aptitudes de l’individu, ce qui permet à chacun d’évoluer à son rythme."],"encart":{"titre":"L’éveil judo, pour les 4-5 ans","texte":"Une pédagogie adaptée, qui permet le développement physique et intellectuel des très jeunes pratiquants. Le programme éveil judo est délibérément construit autour de l’intérêt de l’enfant, pour faciliter ses futurs apprentissages du judo et des activités sportives et artistiques en général."}},{"id":"jujitsu","nom":"Jujitsu","accroche":"Science, art de la souplesse.","enBref":"le jujitsu pour la self-défense","public":"Art martial et self-défense","paragraphes":["Le jujitsu vise essentiellement à vaincre un adversaire par tous les moyens, en utilisant le minimum de force. De ce fait, les adeptes du jujitsu doivent se conformer à diverses disciplines."],"liste":{"intro":"Il leur faut :","items":["savoir juger et utiliser la force de l’adversaire ;","esquiver ses attaques le plus possible ;","déséquilibrer l’adversaire ;","savoir attaquer ses points faibles ;","savoir le renverser à l’aide de la technique du levier ;","être capable de l’immobiliser à terre ;","savoir le frapper."]},"conclusion":"Le jujitsu est proposé comme art martial : une véritable méthode de self-défense, efficace et attrayante, qui permet d’améliorer l’ensemble des qualités physiques et mentales."},{"id":"taiso","nom":"Taïso","accroche":"Un sport en douceur qui accueille tout public.","enBref":"le taïso pour garder la forme","public":"Tout public","paragraphes":["Le taïso se pratique de façon décontractée, dans des tenues amples permettant des mouvements aisés. C’est une excellente solution pour éliminer le stress accumulé pendant la journée, et cela dans une ambiance conviviale.","Véritable échauffement, il permet de garder la forme et d’améliorer sa condition physique. Du petit matériel peut être utilisé : des élastiques, des cerceaux, des bâtons…","Son objectif est de permettre l’entretien et l’amélioration du potentiel de chaque pratiquant, en utilisant des exercices adaptés à l’âge et aux aptitudes de chacun.","Ces exercices améliorent le système cardio-vasculaire et le système respiratoire, le fonctionnement du système neuromusculaire, les qualités musculaires ainsi que les amplitudes articulaires."],"conclusion":"Exercices d’échauffement précédant une activité physique, mais aussi exercices spécifiques de renforcement musculaire, d’étirement ou de relaxation : le taïso est une méthode accessible à tous, et non réservée aux seuls pratiquants d’arts martiaux."},{"id":"yoga","nom":"Yoga","accroche":"Postures, respiration et détente, chacun à son rythme.","enBref":"le yoga pour la souplesse et la détente","public":"Lundi et jeudi","paragraphes":["Le yoga associe des postures, un travail sur la respiration et des temps de relaxation. Chacun pratique à son rythme, sans esprit de compétition.","Il entretient la souplesse, le tonus musculaire et l’équilibre, et aide à relâcher les tensions du quotidien."],"conclusion":"Les séances ont lieu au dojo le lundi et le jeudi : un cours par semaine ou les deux, au choix (voir les tarifs)."}]}', 'publie'),
  ('partenaires', '{"partenaires":[{"nom":"Sof’t Café","activite":"Tabac · Presse · Loto · PMU · Librairie · Café","adresse":"60 avenue de Limoges, 87920 Condat-sur-Vienne","provisoire":true},{"nom":"Partenaire à compléter","activite":"Activité du partenaire","adresse":"Adresse du partenaire, 87920 Condat-sur-Vienne","provisoire":true}]}', 'publie'),
  ('reglement', '{"miseAJour":"septembre 2026","articles":[{"titre":"Licence","paragraphes":["Chaque pratiquant doit être licencié à France Judo (Fédération française de judo, jujitsu, kendo et disciplines associées) pour la saison en cours.","La licence se prend chaque saison, en ligne sur l’espace licencié de la fédération ou par l’intermédiaire du club."]},{"titre":"Santé : questionnaire ou certificat médical","paragraphes":["Les formalités médicales dépendent de l’âge du pratiquant :"],"liste":["Pratiquant mineur : plus de certificat médical systématique. Le questionnaire de santé du sportif mineur est rempli en famille (ses réponses restent confidentielles) et les parents signent une attestation, remise au club. Si l’une des réponses est positive, un certificat médical d’absence de contre-indication datant de moins de 6 mois est nécessaire.","Pratiquant majeur : un certificat médical d’absence de contre-indication à la pratique du judo est demandé pour la première licence. Au renouvellement, le questionnaire de santé QS-SPORT suffit si toutes les réponses sont négatives ; sinon, un certificat médical datant de moins de 6 mois est nécessaire."],"apresListe":"Si le club n’est pas en possession de ces documents, l’accès au tatami sera refusé au pratiquant."},{"titre":"Responsabilité des parents","paragraphes":["Les parents sont responsables de leurs enfants :"],"liste":["jusqu’à l’arrivée du professeur ;","après la fin de la séance d’entraînement."],"apresListe":"Pour assurer un meilleur déroulement des cours et ne pas déconcentrer les pratiquants, il est demandé aux parents de ne pas assister aux cours, sauf autorisation exceptionnelle du professeur."},{"titre":"Ponctualité","paragraphes":["Les pratiquants doivent arriver à l’heure à leur cours et ne peuvent le quitter sans l’autorisation du professeur.","Les parents ou les représentants légaux des enfants doivent venir chercher les jeunes pratiquants à la fin du cours et avant le début du cours suivant."]},{"titre":"Tenue","liste":["Le pratiquant ne peut pénétrer sur le tatami qu’en judogi (kimono).","Port du tee-shirt sous le judogi pour les filles.","Tous les bijoux sont interdits sur les tatamis (montres, bracelets, etc.).","Le pratiquant doit se déplacer dans le dojo et ses abords immédiats en claquettes.","Prévoir une petite bouteille d’eau à déposer au bord des tatamis."]},{"titre":"Dossier d’inscription","paragraphes":["Le dossier d’inscription se compose :"],"liste":["d’une fiche de renseignements ;","de l’attestation du questionnaire de santé (mineur), ou du certificat médical ou de l’attestation QS-SPORT (majeur) — voir l’article « Santé » ;","de la licence France Judo de la saison."]},{"titre":"Hygiène","paragraphes":["Tous les membres, parents et visiteurs sont tenus de veiller à la propreté générale du dojo :"],"liste":["utiliser les poubelles ;","ne pas circuler pieds nus dans les locaux ;","maintenir propres les abords des tatamis."]},{"titre":"Animation et compétition","paragraphes":["Pour participer aux animations et aux compétitions, les judokas doivent avoir :"],"liste":["une licence France Judo de la saison en cours ;","un justificatif d’identité : le passeport sportif France Judo ou tout autre document ;","des formalités médicales en règle (questionnaire ou certificat, selon l’âge)."],"apresListe":"Pour les pratiquants mineurs, la mention « compétition » figure par défaut sur la licence."},{"titre":"Saison sportive","paragraphes":["Les cours sont assurés pendant toute la saison sportive, de septembre à juin. Ils ne sont pas assurés pendant les vacances scolaires et les jours fériés."]}],"sources":[{"libelle":"France Judo — licences : le certificat médical n’est plus obligatoire (mineurs)","url":"https://www.ffjudo.com/actualite/licences-questionnaire-mineurs"},{"libelle":"France Judo — textes officiels 2026/2027, règlement des compétitions","url":"https://www.ffjudo.com/resource-file/document/1788351916_934d7a5b8ec332121fc7.pdf"}]}', 'publie'),
  ('liens', '{"liens":[{"libelle":"France Judo","description":"Fédération française de judo et disciplines associées","url":"https://www.ffjudo.com/"},{"libelle":"Prendre sa licence","description":"Espace licencié France Judo","url":"https://moncompte.ffjudo.com/prise-licence"},{"libelle":"Passages de grades","description":"Règles et programmes, France Judo","url":"https://www.ffjudo.com/passages-de-grades"},{"libelle":"Mairie de Condat-sur-Vienne","description":"Site de la commune","url":"https://www.condatsurvienne.fr/"}]}', 'publie');

